"""Unit tests for the helpers behind compare.run_claims."""

from pathlib import Path

import numpy as np
import pytest

from rllab.compare import ClaimSpec, run_claims
from rllab.compare.claims import PERMUTATIONS, holm, permutation_p_value, ratio_holds
from rllab.evaluate import ScoreSet
from rllab.viz import Chart


def _sets(name: str, *chunks: list[float]) -> tuple[ScoreSet, ...]:
    return tuple(
        ScoreSet(player=name, train_seed=i, scores=np.asarray(c, dtype=np.float64), games=())
        for i, c in enumerate(chunks)
    )


def test_holm_matches_hand_computed_values() -> None:
    # sorted 0.01, 0.02, 0.04 -> 3*0.01, 2*0.02, max(0.04, 1*0.04)
    assert holm([0.04, 0.01, 0.02]) == pytest.approx([0.04, 0.03, 0.04])


def test_holm_is_monotone_and_capped_at_one() -> None:
    assert holm([0.5, 0.6]) == pytest.approx([1.0, 1.0])
    assert holm([0.001]) == pytest.approx([0.001])


def test_permutation_p_value_is_smallest_possible_for_separated_samples() -> None:
    x = np.full(50, 10.0)
    y = np.zeros(50)
    assert permutation_p_value(x, y) == pytest.approx(1 / (PERMUTATIONS + 1))


def test_permutation_p_value_is_one_when_x_is_lower() -> None:
    assert permutation_p_value(np.zeros(50), np.full(50, 10.0)) == 1.0


def test_ratio_bar_is_inclusive_and_strict_below() -> None:
    assert ratio_holds(9.0, 10.0, 0.9)
    assert ratio_holds(2.7, 3.0, 0.9)
    assert not ratio_holds(8.99, 10.0, 0.9)


def test_scores_are_pooled_across_seeds(tmp_path: Path) -> None:
    scores = {"a": _sets("a", [1.0, 2.0], [6.0]), "b": _sets("b", [0.0], [0.0, 0.0])}
    spec = ClaimSpec(name="a>b", a="a", b="b", direction="greater")
    (claim,) = run_claims(scores, [spec], out=tmp_path)
    assert claim.mean_a == pytest.approx(3.0)
    assert claim.mean_b == 0.0


def test_not_worse_fails_when_ratio_bar_missed(tmp_path: Path) -> None:
    scores = {"a": _sets("a", [8.0, 9.0]), "b": _sets("b", [10.0, 9.0])}
    spec = ClaimSpec(name="a~b", a="a", b="b", direction="not_worse", min_ratio=0.95)
    (claim,) = run_claims(scores, [spec], out=tmp_path)
    assert claim.p_corrected > 0.05
    assert claim.passed is False


def test_report_links_cross_play_charts(tmp_path: Path) -> None:
    scores = {"a": _sets("a", [1.0, 2.0]), "b": _sets("b", [1.0, 2.0])}
    spec = ClaimSpec(name="a>b", a="a", b="b", direction="greater")
    chart = Chart(path=Path("crossplay/fish.png"), groups=("a",), baselines=())
    run_claims(scores, [spec], charts=[chart], out=tmp_path)
    text = (tmp_path / "report.md").read_text()
    assert "## Cross-play" in text
    assert "(crossplay/fish.png)" in text
    assert "Holm over 1 claim" in text

